using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Collections.Generic;
sealed partial class WorkspaceWindow {
 Dictionary<string,object> LiveCompanion(){string config=Environment.GetEnvironmentVariable("JAGO_COMPANION_DATA")??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Jago Companion Preview");var files=new List<string>{Path.Combine(config,"workscape-live.json")};foreach(string shared in new[]{SharedRoot,Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Jago Studio Suite"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Jago Installer Preview","Suite")}.Distinct()){string folder=Path.Combine(shared,"OpenStudios");if(Directory.Exists(folder))files.AddRange(Directory.GetFiles(folder,"*.json"));}foreach(string file in files)try{if(!File.Exists(file))continue;var record=json.Deserialize<Dictionary<string,object>>(ReadShared(file));if(Convert.ToString(record["studio"])!="companion"||!record.ContainsKey("config")||!String.Equals(Path.GetFullPath(Convert.ToString(record["config"])),Path.GetFullPath(config),StringComparison.OrdinalIgnoreCase))continue;var process=Process.GetProcessById(Convert.ToInt32(record["pid"]));if(process.HasExited||!String.Equals(process.MainModule.FileName,Convert.ToString(record["exe"]),StringComparison.OrdinalIgnoreCase)||!record.ContainsKey("started")||DateTime.Parse(Convert.ToString(record["started"])).ToUniversalTime()!=process.StartTime.ToUniversalTime())continue;string folder=Path.GetFullPath(Convert.ToString(record["folder"]));if(!Directory.Exists(folder)||!File.Exists(Path.Combine(folder,"ready.json")))continue;ValidateStudio("companion",process.MainModule.FileName);return record;}catch{}return null;}
 bool TakeLiveCompanion(WorkTab tab){var live=LiveCompanion();if(live==null)return false;string owner=Convert.ToString(live["owner"]);if(!String.IsNullOrEmpty(owner)&&owner!=session)return false;var process=Process.GetProcessById(Convert.ToInt32(live["pid"]));if(items.Any(t=>t!=tab&&t.process!=null&&!t.process.HasExited&&t.process.Id==process.Id))return false;tab.process=process;tab.folder=Convert.ToString(live["folder"]);tab.id=Path.GetFileName(tab.folder);tab.attached=false;SetStatus("Bringing your live Companion into Workscape…");return true;}
}
